import { createChart, removeChart } from '../../test/ut/core/utHelper';
import { EChartsType } from '../../src/echarts.all';
import Displayable from 'zrender/src/graphic/Displayable';

function getMarkerDisplayableZs(chart: EChartsType, mainType: string): number[] {
    const views = (chart as any)._componentsViews as any[];
    const view = views.filter(v => v.type === mainType)[0];
    const zs: number[] = [];
    view.markerGroupMap.each(function (item: {group: Displayable}) {
        item.group.traverse(function (el: Displayable) {
            if (!el.isGroup) {
                zs.push(el.z);
            }
        });
    });
    return zs;
}

describe('marker_z_option', function () {

    let chart: EChartsType;
    afterEach(function () {
        if (chart) {
            removeChart(chart);
            chart = null;
        }
    });

    function makeOption(markerOpt: object) {
        return {
            xAxis: { type: 'category', data: ['a', 'b', 'c'] },
            yAxis: {},
            series: [{
                type: 'line',
                data: [1, 2, 3],
                ...markerOpt
            }]
        } as any;
    }

    it('markPoint supports z option', function () {
        chart = createChart();
        chart.setOption(makeOption({
            markPoint: { z: 2, data: [{ type: 'max' }] }
        }));
        const zs = getMarkerDisplayableZs(chart, 'markPoint');
        expect(zs.length).toBeGreaterThan(0);
        zs.forEach(z => expect(z).toEqual(2));
    });

    it('markLine supports z option', function () {
        chart = createChart();
        chart.setOption(makeOption({
            markLine: { z: 3, data: [{ type: 'average' }] }
        }));
        const zs = getMarkerDisplayableZs(chart, 'markLine');
        expect(zs.length).toBeGreaterThan(0);
        zs.forEach(z => expect(z).toEqual(3));
    });

    it('markArea supports z option', function () {
        chart = createChart();
        chart.setOption(makeOption({
            markArea: { z: 4, data: [[{ xAxis: 'a' }, { xAxis: 'b' }]] }
        }));
        const zs = getMarkerDisplayableZs(chart, 'markArea');
        expect(zs.length).toBeGreaterThan(0);
        zs.forEach(z => expect(z).toEqual(4));
    });

    it('default z is kept when not specified', function () {
        chart = createChart();
        chart.setOption(makeOption({
            markPoint: { data: [{ type: 'max' }] }
        }));
        const zs = getMarkerDisplayableZs(chart, 'markPoint');
        expect(zs.length).toBeGreaterThan(0);
        zs.forEach(z => expect(z).toEqual(5));
    });
});
